<!-- This file is generated by AI. -->

<!--
  选项卡栏。

  实现要点 (每条都是踩过坑才定下来的):

  * **拖拽用指针事件, 不用 HTML5 DnD**: 后者在部分 WebView 中不可靠 (拖拽影像不跟手、
    drop 不触发)。阈值 6px 才判定为拖拽, 否则与"点击选中"冲突。
  * **几何测量是命令式的**: 量出各选项卡相对滚动内容的 left/width 交给纯函数
    (`dropSlot` / `slotToIndex` / `dropIndicator`) 算落点。拖动过程中**不重排** tabs ——
    一旦在 pointermove 里重排, 落点会跟着漂。
  * **Ctrl+Tab 走最近使用顺序**, 并且在按住 Ctrl 期间维持同一个候选序列 (否则每按一次
    都会从头算, 变成"在两个 tab 之间反复横跳")。
  * 子元素上的关闭按钮与模式开关不触发拖拽。
-->

<script lang="ts">
  import { revealItemInDir } from '@tauri-apps/plugin-opener';
  import { onMount } from 'svelte';

  import { requestCloseTab } from '../tabs/close';
  import { dropIndicator, dropSlot, slotToIndex, type TabBox } from '../tabs/dnd';
  import type { WorkbenchTabItem } from '../tabs/model';
  import { buildTabMenu, localPathOf } from '../tabs/menu';
  import { cycleRecentTab, recentTabIds } from '../tabs/order';
  import { actions, appStore } from '../state/store.svelte';
  import { isSceneInVoiceMode, setSceneVoiceMode, voiceWorkbenchOpen } from '../voice/mode';
  import ContextMenu, { type ContextMenuItem } from './ContextMenu.svelte';
  import FileBadges from './FileBadges.svelte';
  import Icon from './Icon.svelte';

  const DRAG_THRESHOLD = 6;

  let { onLocateTab }: { onLocateTab?: (path: string, kind: 'scene' | 'resource' | 'config') => void } = $props();

  let container: HTMLDivElement | undefined = $state();
  let dragState: { id: string; startX: number; active: boolean } | null = null;
  let tabSwitch: { ids: string[]; currentId: string | null } | null = null;
  let draggingId = $state<string | null>(null);
  let indicator = $state<{ id: string; side: 'before' | 'after' } | null>(null);
  let contextMenu = $state<{ x: number; y: number; tab: WorkbenchTabItem } | null>(null);

  const tabs = $derived(appStore.tabs);
  const activeTabId = $derived(appStore.activeTabId);
  const workbenchOpen = $derived(voiceWorkbenchOpen());

  onMount(() => {
    const onKeyDown = (event: KeyboardEvent) => {
      const commandKey = event.ctrlKey || event.metaKey;
      if (!commandKey || event.altKey) return;
      const key = event.key.toLowerCase();

      if (key === 'w' || key === 'f4') {
        tabSwitch = null;
        event.preventDefault();
        const active = appStore.tabs.find((tab) => tab.id === appStore.activeTabId);
        if (active) requestCloseTab(active);
        return;
      }

      if (key === 'tab') {
        if (appStore.tabs.length <= 1) {
          tabSwitch = null;
          return;
        }
        event.preventDefault();
        if (!tabSwitch || appStore.activeTabId !== tabSwitch.currentId) {
          tabSwitch = {
            ids: recentTabIds(appStore.tabs, appStore.tabHistory),
            currentId: appStore.activeTabId,
          };
        }
        const current = tabSwitch;
        const available = new Set(appStore.tabs.map((tab) => tab.id));
        const ids = current.ids.filter((id) => available.has(id));
        const nextId = cycleRecentTab(ids, current.currentId, event.shiftKey ? -1 : 1);
        if (!nextId) return;
        current.ids = ids;
        current.currentId = nextId;
        actions.activateTab(nextId);
      }
    };

    const onKeyUp = (event: KeyboardEvent) => {
      if (event.key === 'Control' || event.key === 'Meta') tabSwitch = null;
    };
    const onBlur = () => {
      tabSwitch = null;
    };

    window.addEventListener('keydown', onKeyDown);
    window.addEventListener('keyup', onKeyUp);
    window.addEventListener('blur', onBlur);
    return () => {
      window.removeEventListener('keydown', onKeyDown);
      window.removeEventListener('keyup', onKeyUp);
      window.removeEventListener('blur', onBlur);
    };
  });

  /**
   * 测量各选项卡的位置。
   *
   * 基准是 `container` 左边缘减去 `scrollLeft`, 因此横向滚动时仍然正确
   * (指针坐标也要做同样的换算, 见 `pointerInContent`)。
   */
  function measure(): TabBox[] {
    if (!container) return [];
    const base = container.getBoundingClientRect().left - container.scrollLeft;
    return [...container.querySelectorAll<HTMLElement>('.tab-strip-item')].map((node) => {
      const rect = node.getBoundingClientRect();
      return { id: node.dataset.tabId ?? '', left: rect.left - base, width: rect.width };
    });
  }

  /** 指针位置换算到"滚动内容坐标系" */
  function pointerInContent(clientX: number): number | null {
    if (!container) return null;
    return clientX - container.getBoundingClientRect().left + container.scrollLeft;
  }

  function onPointerDown(event: PointerEvent & { currentTarget: HTMLDivElement }, tab: WorkbenchTabItem) {
    if (event.button !== 0) return;
    const target = event.target as HTMLElement | null;
    // 关闭按钮与模式开关不触发拖拽
    if (target?.closest('.tab-strip-close') || target?.closest('.tab-strip-action')) return;
    dragState = { id: tab.id, startX: event.clientX, active: false };
    event.currentTarget.setPointerCapture(event.pointerId);
  }

  function onPointerMove(event: PointerEvent) {
    const state = dragState;
    if (!state) return;
    if (!state.active) {
      if (Math.abs(event.clientX - state.startX) < DRAG_THRESHOLD) return;
      state.active = true;
      draggingId = state.id;
    }
    const pointerX = pointerInContent(event.clientX);
    if (pointerX === null) return;
    indicator = dropIndicator(appStore.tabs, state.id, dropSlot(measure(), pointerX));
  }

  function endDrag(event: PointerEvent) {
    const state = dragState;
    dragState = null;
    draggingId = null;
    indicator = null;
    if (!state?.active) return;

    const pointerX = pointerInContent(event.clientX);
    if (pointerX === null) return;
    const slot = dropSlot(measure(), pointerX);
    const target = slot === null ? null : slotToIndex(appStore.tabs, state.id, slot);
    if (target !== null) actions.moveTab(state.id, target);
  }

  function isDirtyTab(tab: WorkbenchTabItem): boolean {
    if (tab.kind !== 'scene' && tab.kind !== 'resource' && tab.kind !== 'config') return false;
    return appStore.documents.some((doc) => doc.path === tab.path && doc.dirty);
  }

  const menuItems = $derived<ContextMenuItem[]>(contextMenu ? buildMenu(contextMenu.tab) : []);

  /** 菜单项由 `tabs/menu.ts` 决定 (那里有单测钉住"一项都不能少"), 组件只把动作接上。 */
  function buildMenu(tab: WorkbenchTabItem): ContextMenuItem[] {
    return buildTabMenu(
      tabs,
      tab,
      {
        closeTab: (target) => requestCloseTab(target),
        closeMany: (targets) => targets.forEach((target) => requestCloseTab(target)),
        sortTabs: (ordered) => actions.sortTabs(ordered),
        revealInFileManager: (path) => void revealItemInDir(path),
        locateInBrowser: (target) => {
          // 三种有磁盘位置的卡各自对应一个去处: 场景页 / 资源页 / 项目页 (配置卡没有自己的浏览器)
          if (target.kind === 'scene') onLocateTab?.(target.path, 'scene');
          else if (target.kind === 'resource') onLocateTab?.(target.path, 'resource');
          else if (target.kind === 'config') onLocateTab?.(target.path, 'config');
        },
      },
      isDirtyTab
    );
  }

  /**
   * 场景卡最左侧的配音编辑模式开关。
   *
   * 可见性规则集中在 `shouldShowVoiceToggle` 一处定义、一处测试: 工作台未打开时不显示;
   * 已在配音编辑模式的卡始终显示; 否则只在当前选中的卡上显示。
   *
   * **不可见时直接不渲染**, 不保留任何占位 —— 只要留一个空槽, 没有图标的选项卡标题前面
   * 就会多出一段死留白。
   */
  function voiceToggleOf(tab: WorkbenchTabItem): 'on' | 'off' | null {
    if (!workbenchOpen || tab.kind !== 'scene') return null;
    const inVoiceMode = appStore.voiceModePaths.includes(tab.path) || tab.id === activeTabId;
    if (!inVoiceMode) return null;
    return isSceneInVoiceMode(tab.path) ? 'on' : 'off';
  }
</script>

<div class="tab-strip" bind:this={container} role="tablist">
  {#each tabs as tab (tab.id)}
    <!-- {#each} 的直接子节点才能放 `{@const}`; 放在下面的 div 里 Svelte 会报错 -->
    {@const localPath = localPathOf(tab)}
    <div
      class="tab-strip-item"
      class:active={tab.id === activeTabId}
      class:dragging={tab.id === draggingId}
      class:drop-before={indicator?.id === tab.id && indicator.side === 'before'}
      class:drop-after={indicator?.id === tab.id && indicator.side === 'after'}
      role="tab"
      tabindex="0"
      aria-selected={tab.id === activeTabId}
      data-tab-id={tab.id}
      title={tab.tooltip}
      onpointerdown={(event) => onPointerDown(event, tab)}
      onpointermove={onPointerMove}
      onpointerup={endDrag}
      onpointercancel={endDrag}
      onclick={() => actions.activateTab(tab.id)}
      onkeydown={(event) => {
        if (event.key !== 'Enter' && event.key !== ' ') return;
        event.preventDefault();
        actions.activateTab(tab.id);
      }}
      oncontextmenu={(event) => {
        event.preventDefault();
        contextMenu = { x: event.clientX, y: event.clientY, tab };
      }}
      onauxclick={(event) => {
        // 中键关闭 (与浏览器一致)
        if (event.button !== 1) return;
        event.preventDefault();
        requestCloseTab(tab);
      }}
    >
      {#if voiceToggleOf(tab) !== null && tab.kind === 'scene'}
        {@const sceneTab = tab}
        {@const inVoiceMode = voiceToggleOf(tab) === 'on'}
        <button
          type="button"
          class="tab-strip-action"
          class:on={inVoiceMode}
          title={inVoiceMode ? '退出配音编辑模式' : '进入配音编辑模式'}
          onclick={(event) => {
            event.stopPropagation();
            setSceneVoiceMode(sceneTab.path, !inVoiceMode);
          }}
        >
          <Icon name={inVoiceMode ? 'Mic' : 'MicProhibited'} size={14} />
        </button>
      {/if}

      {#if tab.icon}
        <span class="tab-strip-icon"><Icon name={tab.icon} size={16} /></span>
      {/if}

      <!--
        内容必须是 `●` 本身而不是留空: `.tab-strip-dirty` 只给了 color 与 font-size,
        空 span 的宽度是 0 —— 脏标记会完全看不见。

        位置在**图标之前**、标题之内: 脏点 / 图标 / 标题同属"这一页自己"的信息, 与右侧那些
        "这个文件现在的状态"(git、诊断) 分开。
      -->
      {#if isDirtyTab(tab)}
        <span class="tab-strip-dirty" title="有未保存的更改">●</span>
      {/if}

      <span class="tab-strip-title">
        {tab.title}
        <!-- 配音队列角标: 留在标题**之内**, 它修饰的是"这一页"而不是文件状态 -->
        {#if tab.kind === 'voice-workbench' && appStore.voiceQueuePending > 0}
          <span class="tab-strip-badge">{appStore.voiceQueuePending}</span>
        {/if}
      </span>

      <!--
        文件状态徽标 (git 更改字母 + 错误/警告计数), 放在**标题之后、关闭按钮之前**。

        放这里不用担心挤掉标题: 选项卡条本身就是横向滚动容器
        (`.tab-strip { overflow-x: auto }`), 标题也没有 `max-width` —— 宽度不够时是**整条
        滚动**, 而不是把标题压成省略号。只给有磁盘实体的选项卡 (场景/资源/配置) 挂 ——
        工作台、说明页、预处理页没有对应文件。
      -->
      {#if localPath}
        <FileBadges path={localPath} />
      {/if}

      <button
        type="button"
        class="tab-strip-close"
        title="关闭"
        aria-label="关闭 {tab.title}"
        onclick={(event) => {
          event.stopPropagation();
          requestCloseTab(tab);
        }}
      >
        <Icon name="Dismiss" size={12} />
      </button>
    </div>
  {/each}
</div>

{#if contextMenu}
  <ContextMenu x={contextMenu.x} y={contextMenu.y} items={menuItems} onClose={() => (contextMenu = null)} />
{/if}
